mapper.select:
SELECT payment_id, user_id, benefit_id, card_id, partner_order_id, tid, amount, discount_amount, final_amount, status, error_message, TO_CHAR(created_at, 'YYYY-MM-DD HH24:MI:SS') AS created_at, TO_CHAR(updated_at, 'YYYY-MM-DD HH24:MI:SS') AS updated_at FROM payment_logs
user_id = #{userId}
AND status = #{status}
ORDER BY created_at DESC
